import React, { useState, useEffect, useRef } from 'react';
import { Music, Play, Pause } from 'lucide-react';

/**
 * MusicRelaxSection:
 * Plays gentle, minimalist chime tones generated by the Web Audio API.
 * Elegant and calming atmosphere.
 */
export default function MusicRelaxSection() {
  const [isPlaying, setIsPlaying] = useState(false);
  const audioCtxRef = useRef(null);
  const timerRef = useRef(null);

  const notes = [
    261.63, 329.63, 392.00, 523.25, 440.00, 392.00, 329.63,
    293.66, 349.23, 440.00, 392.00, 329.63, 261.63, 392.00,
    349.23, 329.63, 293.66, 261.63
  ];

  const playTone = (freq, duration = 1.4) => {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!audioCtxRef.current) {
        audioCtxRef.current = new AudioContext();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') {
        ctx.resume();
      }

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime);

      gain.gain.setValueAtTime(0.001, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.12, ctx.currentTime + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + duration);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start();
      osc.stop(ctx.currentTime + duration);
    } catch (e) {
      console.warn("Audio error:", e);
    }
  };

  const startMusic = () => {
    setIsPlaying(true);
    let noteIndex = 0;
    timerRef.current = setInterval(() => {
      playTone(notes[noteIndex % notes.length]);
      noteIndex++;
    }, 750);
  };

  const stopMusic = () => {
    setIsPlaying(false);
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => {
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, []);

  return (
    <div className="max-w-2xl mx-auto py-6">
      <div className="bg-white rounded-2xl p-6 sm:p-8 border border-stone-200 shadow-sm text-center">
        <div className="w-12 h-12 mx-auto rounded-xl bg-stone-100 text-stone-800 flex items-center justify-center mb-4">
          <Music className="w-6 h-6 text-stone-700" />
        </div>

        <h2 className="text-xl sm:text-2xl font-serif font-bold text-stone-900 mb-2">Momento di Calma</h2>
        <p className="text-stone-600 text-xs sm:text-sm mb-6 max-w-md mx-auto">
          Una sequenza di note sobrie e armoniose generate in tempo reale. Uno spazio dedicato alla tranquillità e alla riflessione.
        </p>

        <div className="flex items-center justify-center gap-4">
          <button
            onClick={isPlaying ? stopMusic : startMusic}
            className={`inline-flex items-center gap-2 px-6 py-2.5 rounded-xl font-medium text-xs sm:text-sm transition ${
              isPlaying
                ? 'bg-stone-200 text-stone-800 hover:bg-stone-300'
                : 'bg-stone-900 text-white hover:bg-stone-800'
            }`}
          >
            {isPlaying ? (
              <>
                <Pause className="w-4 h-4 fill-current" />
                <span>Interrompi</span>
              </>
            ) : (
              <>
                <Play className="w-4 h-4 fill-current" />
                <span>Ascolta Melodia</span>
              </>
            )}
          </button>
        </div>

        <div className="flex items-center justify-center gap-1.5 mt-8 h-10">
          {[35, 60, 25, 80, 50, 90, 45, 75, 40, 55].map((height, idx) => (
            <div
              key={idx}
              className={`w-1.5 rounded-full bg-stone-400 transition-all duration-300 ${
                isPlaying ? 'opacity-80' : 'opacity-25'
              }`}
              style={{
                height: isPlaying ? `${height}%` : '20%',
                animationDelay: `${idx * 0.1}s`
              }}
            />
          ))}
        </div>

        <p className="text-xs text-stone-400 mt-5 font-sans">
          Spazio riservato ad Ele
        </p>
      </div>
    </div>
  );
}
